    ms' = MS (mkR (Z_to_bv 64 (8 * i)) sp gp tp (Z_to_bv 64 3) (Z_to_bv 64 LS) (Z_to_bv 64 LD) s0 (Z_to_bv 64 rf) a0' a1' a2' a3' a4' a5' (Z_to_bv 64 1) (Z_to_bv 64 1)
