                  (Z_to_bv 64 (ap_w p)) (Z_to_bv 64 (ap_w p)) (Z_to_bv 64 (LS + ap_w p)) (Z_to_bv 64 (LD + ap_w p)))
             F' (Z_to_bv 64 0xd05d8) fc' None m' (seg_rom asegs)
    /\ fs_agree F F' /\ frm0 fc' /\ munch [(ap_DD p, ap_DD p + ap_N p)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

