(* [comment removed for export] *)
Lemma ap_j_loop : forall (n : nat) (p : app) (rf i j LS LD : Z)
    (sp gp tp s0 a0 a1 a2 a3 a4 a5 s2 s3 s8 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem),
  Z.of_nat n = ap_w p - j -> 0 <= j -> (1 <= n)%nat -> 0 <= i < ap_h p -> ap_ok p -> rf_ok p rf -> frm0 fc ->
  ap_DS p <= LS -> LS + 4 * ap_wpl p <= ap_DS p + ap_N p -> ap_DD p <= LD -> LD + 4 * ap_wpl p <= ap_DD p + ap_N p ->
  (forall m', munch [(ap_DD p, ap_DD p + ap_N p)] m m' -> wmono asegs m m' -> ap_ro p rf m') ->
  wr_at asegs m (ap_DD p) (ap_N p) -> acc asegs m (ap_DD p) (ap_N p) -> mem_inv asegs m ->
  evt asegs (ap_j_exit p rf i LS LD sp gp tp s0 F m)
    (MS (mkR (Z_to_bv 64 (8 * i)) sp gp tp (Z_to_bv 64 3) (Z_to_bv 64 LS) (Z_to_bv 64 LD) s0 (Z_to_bv 64 rf) a0 a1 a2 a3 a4 a5 (Z_to_bv 64 1) (Z_to_bv 64 1)
             s2 s3 (Z_to_bv 64 (ap_KF p)) (Z_to_bv 64 i) (Z_to_bv 64 (LS + j)) (Z_to_bv 64 (LD + j)) s8
             (Z_to_bv 64 (ap_LS p)) (Z_to_bv 64 (ap_KI p)) (Z_to_bv 64 2147450880)
             (Z_to_bv 64 j) (Z_to_bv 64 j) (Z_to_bv 64 (LS + j)) (Z_to_bv 64 (LD + j)))
        F (Z_to_bv 64 0xd06e4) fc None m (seg_rom asegs)).
