(* [comment removed for export] *)
Definition ap_i_exit (p : app) (rf : Z) (sp gp tp s0 : word) (F : bvmap 5 word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (ra' t1' t2' a0' a1' a2' a3' a4' a5' s2' s3' s5' s6' s7' s8' t3' t4' t5' t6' : word) (F' : bvmap 5 word) (fc' : bv 32) (m' : mem),
    ms' = MS (mkR ra' sp gp tp (Z_to_bv 64 3) t1' t2' s0 (Z_to_bv 64 rf) a0' a1' a2' a3' a4' a5' (Z_to_bv 64 1) (Z_to_bv 64 1)
                  s2' s3' (Z_to_bv 64 (ap_KF p)) s5' s6' s7' s8' (Z_to_bv 64 (ap_LS p)) (Z_to_bv 64 (ap_KI p)) (Z_to_bv 64 2147450880) t3' t4' t5' t6')
             F' (Z_to_bv 64 0xd0a3c) fc' None m' (seg_rom asegs)
    /\ fs_agree F F' /\ frm0 fc' /\ munch (ap_W p rf) m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

(* [comment removed for export] *)
Lemma ap_i_loop : forall (n : nat) (p : app) (rf i : Z)
    (ra sp gp tp t1 t2 s0 a0 a2 a3 a5 s2 s3 s5 s6 s7 s8 t3 t4 t5 t6 x104 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem),
  Z.of_nat n = ap_h p - i -> 0 <= i -> (1 <= n)%nat -> ap_ok p -> rf_ok p rf -> frm0 fc ->
  (forall m', munch (ap_W p rf) m m' -> wmono asegs m m' -> ap_ro p rf m') ->
  rw_cells asegs m (rf + 72) [C8 (Z_to_bv 64 (i * ap_wpl p)); C8 (Z_to_bv 64 (i * ap_wpl p))] -> rw_cells asegs m (rf + 104) [C8 x104] ->
  wr_at asegs m (ap_DD p) (ap_N p) -> acc asegs m (ap_DD p) (ap_N p) -> mem_inv asegs m ->
  evt asegs (ap_i_exit p rf sp gp tp s0 F m)
    (MS (mkR ra sp gp tp (Z_to_bv 64 3) t1 t2 s0 (Z_to_bv 64 rf) a0 (Z_to_bv 64 (ap_wpl p)) a2 a3 (Z_to_bv 64 i) a5 (Z_to_bv 64 1) (Z_to_bv 64 1)
             s2 s3 (Z_to_bv 64 (ap_KF p)) s5 s6 s7 s8 (Z_to_bv 64 (ap_LS p)) (Z_to_bv 64 (ap_KI p)) (Z_to_bv 64 2147450880) t3 t4 t5 t6)
        F (Z_to_bv 64 0xd060c) fc None m (seg_rom asegs)).
Proof.
